 * @throws {Error} Throws an error if the file cannot be read (e.g., file not found, permissions issue).
 */
async function countLinesInFile(filePath) {
    try {
        // 1. Read the file content as a string (using 'utf8' encoding)
        const data = await fs.readFile(filePath, 'utf8');

        // 2. Split the content by newline characters.
        // The split('\n') method will return an array where each element is a line.
        // Note: This simple split might behave slightly differently for files ending
