/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every 'wait' milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new, throttled function.
 */
function throttle(func, wait) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let lastCallTime = 0;

  return function(...args) {
    const context = this;
    const now = Date.now();

    // 1. Check if enough time has passed since the last execution
    if (now - lastCallTime >= wait) {
      // If enough time has passed, execute the function immediately
      lastCallTime = now;
      func.apply(context, args);
    } else {
      // 2. If not enough time has passed, store the latest arguments
      // This ensures that if the function is called multiple times rapidly,
      // we only execute it once after the waiting period.
      lastArgs = args;
      lastThis = context;

      // 3. If there is no pending timeout, set one to execute the function
      // after the wait period. This is the "throttle" mechanism.
      if (!timeout) {
        timeout = setTimeout(() => {
          lastCallTime = Date.now(); // Update time when it finally runs
          timeout = null;
          // Execute the function with the stored arguments and context
          func.apply(lastThis, lastArgs);
          lastArgs = null;
          lastThis = null;
        }, wait - (now - lastCallTime)); // Calculate remaining time for better accuracy
      }
    }
  };
}

